421	function headerMapHasKeyIgnoreCase(
422	  headers: Record<string, string>,
423	  targetKey: string
424	): boolean {
425	  const normalizedTarget = targetKey.trim().toLowerCase();
426	  return Object.keys(headers).some(
427	    (key) => key.trim().toLowerCase() === normalizedTarget
428	  );
429	}
