431	function headerMapGetIgnoreCase(
432	  headers: Record<string, string>,
433	  targetKey: string
434	): string | null {
435	  const normalizedTarget = targetKey.trim().toLowerCase();
436	  const key = Object.keys(headers).find(
437	    (candidate) => candidate.trim().toLowerCase() === normalizedTarget
438	  );
439	  if (!key) return null;
440	  const value = headers[key];
441	  return typeof value === "string" ? value : null;
442	}
