444	function tokenFromAuthorizationHeader(rawHeader: string | null): string | null {
445	  const trimmed = nonEmptyTrimmedString(rawHeader);
446	  if (!trimmed) return null;
447	  const bearerMatch = trimmed.match(/^bearer\s+(.+)$/i);
448	  if (bearerMatch?.[1]) {
449	    return nonEmptyTrimmedString(bearerMatch[1]);
450	  }
451	  return trimmed;
452	}
