454	function parseBooleanLike(value: unknown): boolean | null {
455	  if (typeof value === "boolean") return value;
456	  if (typeof value !== "string") return null;
457	  const normalized = value.trim().toLowerCase();
458	  if (normalized === "true" || normalized === "1") return true;
459	  if (normalized === "false" || normalized === "0") return false;
460	  return null;
