470	export function buildJoinDefaultsPayloadForAccept(input: {
471	  adapterType: string | null;
472	  defaultsPayload: unknown;
473	  paperclipApiUrl?: unknown;
474	  inboundOpenClawAuthHeader?: string | null;
475	  inboundOpenClawTokenHeader?: string | null;
476	}): unknown {
477	  if (input.adapterType !== "openclaw_gateway") {
478	    return input.defaultsPayload;
479	  }
480	
481	  const merged = isPlainObject(input.defaultsPayload)
482	    ? { ...(input.defaultsPayload as Record<string, unknown>) }
483	    : ({} as Record<string, unknown>);
484	
485	  if (!nonEmptyTrimmedString(merged.paperclipApiUrl)) {
486	    const legacyPaperclipApiUrl = nonEmptyTrimmedString(input.paperclipApiUrl);
487	    if (legacyPaperclipApiUrl) merged.paperclipApiUrl = legacyPaperclipApiUrl;
488	  }
489	  const mergedHeaders = normalizeHeaderMap(merged.headers) ?? {};
490	
491	  const inboundOpenClawAuthHeader = nonEmptyTrimmedString(
492	    input.inboundOpenClawAuthHeader
493	  );
494	  const inboundOpenClawTokenHeader = nonEmptyTrimmedString(
495	    input.inboundOpenClawTokenHeader
496	  );
497	  if (
498	    inboundOpenClawTokenHeader &&
499	    !headerMapHasKeyIgnoreCase(mergedHeaders, "x-openclaw-token")
500	  ) {
501	    mergedHeaders["x-openclaw-token"] = inboundOpenClawTokenHeader;
502	  }
503	  if (
504	    inboundOpenClawAuthHeader &&
505	    !headerMapHasKeyIgnoreCase(mergedHeaders, "x-openclaw-auth")
506	  ) {
507	    mergedHeaders["x-openclaw-auth"] = inboundOpenClawAuthHeader;
508	  }
509	
510	  if (Object.keys(mergedHeaders).length > 0) {
511	    merged.headers = mergedHeaders;
512	  } else {
513	    delete merged.headers;
514	  }
515	
516	  const discoveredToken =
517	    headerMapGetIgnoreCase(mergedHeaders, "x-openclaw-token") ??
518	    headerMapGetIgnoreCase(mergedHeaders, "x-openclaw-auth") ??
519	    tokenFromAuthorizationHeader(
520	      headerMapGetIgnoreCase(mergedHeaders, "authorization")
521	    );
522	  if (
523	    discoveredToken &&
524	    !headerMapHasKeyIgnoreCase(mergedHeaders, "x-openclaw-token")
525	  ) {
526	    mergedHeaders["x-openclaw-token"] = discoveredToken;
527	  }
528	
529	  return Object.keys(merged).length > 0 ? merged : null;
530	}
