532	export function mergeJoinDefaultsPayloadForReplay(
533	  existingDefaultsPayload: unknown,
534	  nextDefaultsPayload: unknown
535	): unknown {
536	  if (
537	    !isPlainObject(existingDefaultsPayload) &&
538	    !isPlainObject(nextDefaultsPayload)
539	  ) {
540	    return nextDefaultsPayload ?? existingDefaultsPayload;
541	  }
542	  if (!isPlainObject(existingDefaultsPayload)) {
543	    return nextDefaultsPayload;
544	  }
545	  if (!isPlainObject(nextDefaultsPayload)) {
546	    return existingDefaultsPayload;
547	  }
548	
549	  const merged: Record<string, unknown> = {
550	    ...(existingDefaultsPayload as Record<string, unknown>),
551	    ...(nextDefaultsPayload as Record<string, unknown>)
552	  };
553	
554	  const existingHeaders = normalizeHeaderMap(
555	    (existingDefaultsPayload as Record<string, unknown>).headers
556	  );
557	  const nextHeaders = normalizeHeaderMap(
558	    (nextDefaultsPayload as Record<string, unknown>).headers
559	  );
560	  if (existingHeaders || nextHeaders) {
561	    merged.headers = {
562	      ...(existingHeaders ?? {}),
563	      ...(nextHeaders ?? {})
564	    };
565	  } else if (Object.prototype.hasOwnProperty.call(merged, "headers")) {
566	    delete merged.headers;
567	  }
568	
569	  return merged;
570	}
