572	export function canReplayOpenClawGatewayInviteAccept(input: {
573	  requestType: "human" | "agent";
574	  adapterType: string | null;
575	  existingJoinRequest: Pick<
576	    typeof joinRequests.$inferSelect,
577	    "requestType" | "adapterType" | "status"
578	  > | null;
579	}): boolean {
580	  if (
581	    input.requestType !== "agent" ||
582	    input.adapterType !== "openclaw_gateway"
583	  ) {
584	    return false;
585	  }
586	  if (!input.existingJoinRequest) {
587	    return false;
588	  }
589	  if (
590	    input.existingJoinRequest.requestType !== "agent" ||
591	    input.existingJoinRequest.adapterType !== "openclaw_gateway"
592	  ) {
593	    return false;
594	  }
595	  return (
596	    input.existingJoinRequest.status === "pending_approval" ||
597	    input.existingJoinRequest.status === "approved"
598	  );
599	}
